n(uom, nama) as (values ('karton','Cases'),('box','Boxes'),('pack','Packs'),('inner','Inner Packs'),('pcs','Pieces'),('pair','Pairs'),('unit','Units'),('bag','Bags'),('pail','Pails'),('jerrican','Jerricans'),('drum','Drums'),('ibc','IBC'),('cylinder','Cylinders'),('palet','Pallets'),('skid','Skids'),('crate','Crates'),('jumbo_bag','Jumbo Bags'),('bale','Bales'),('bundle','Bundles'),('roll','Rolls'),('coil','Coils'),('sheet','Sheets / Plates')),
t(kat, uom, au, ak, qty, lbl) as (values ('Cold Chain','kg','karton','ctn-std',15,'karton beku ±15 kg'),('FMCG','liter','karton','ctn-std',12,'karton minuman/minyak 12 L'),('Home Appliances & Furniture','cbm','unit','unit-large',0.6,'unit besar ±0,6 CBM'),('Heavy Cargo & Machinery','ton','crate','heavycargo',3.5,'crate ±3,5 t'),('Heavy Cargo & Machinery','cbm','crate','unitload',2.5,'crate ±2,5 CBM'),('Raw Material & Bulk','ton','jumbo_bag','fibc-1000',1.0,'jumbo bag 1 t'),('Raw Material & Bulk','ton','bag','bag-50',0.05,'sak 50 kg (manual)'),('Building Materials','ton','bag','bag-50',0.05,'sak semen 50 kg (manual)'),('Chemicals (non-DG)','liter','ibc','ibc-1000',1000,'IBC 1.000 L'),('Chemicals (non-DG)','liter','drum','drum-200',200,'drum 200 L'),('Paper, Pulp & Packaging','ton','roll','roll-paper',1.2,'paper roll ±1,2 t'),('General Cargo','ton','bag','bag-50',0.05,'sak 50 kg (manual)'),('General Cargo','cbm','karton','ctn-std',0.05,'karton ±0,05 CBM'),('General Cargo','liter','drum','drum-200',200,'drum 200 L')),
dflt(kode, tool, role) as (values ('unload','Manual','TKBM'),('load','Manual','TKBM'),('putaway','Manual','Inventory Staff'),('pick','RF','Picker'),('inspect','RF','Checker IB'),('check','RF','Checker OB'),('pack','Manual','Packer'),('palletize','Manual','Loader')),
src as (select k.kat, k.uom, k.kelas, concat_ws('; ',
    case when k.uom in ('karton','palet') or (k.uom = 'pcs' and k.kelas = 'light') then 'Benchmark internal Leca (GC)' end,
    case when k.uom in ('karton','bag','pail','jerrican','box') and k.kelas not in ('ctn-light','light','bag-5','pail-5') then 'Gorbel time study (karton 11 kg 1.325/jam; 16 kg 630-850/jam per kru, dibantu alat)' end,
    case when k.uom in ('karton','palet','pcs','pack','box') then 'Carter & Burgess via Cisco-Eagle 2014 (case pick 134/jam; pallet pick 50-65/jam)' end,
    case when k.kelas ~ '(heavy|40|50|xheavy|cyl-std|drum-50|bale-50)' then 'ISO 11228-1 (angkat manual acuan 25 kg)' end,
    case when k.kat = 'Cold Chain' then 'CCOHS/ACGIH cold work + SupplyChainBrain (pick -20 C 130-150 unit/jam)' end) s
  from (select kat, uom, kelas from k union select t.kat, t.au, t.ak from t) k),
src2 as (select kat, uom, kelas, coalesce(nullif(s, ''), 'Estimasi Leca: siklus MHE (forklift/clamp/crane) vs benchmark internal palet') s from src),
dasar as (
  select k.kat, d.uom, d.kelas, d.kode, d.dt, coalesce(f1.v, f2.v, 1.0) fk, coalesce(d.tool, df.tool) tool, coalesce(d.role, df.role) role
  from k join d on d.uom = k.uom and d.kelas = k.kelas join dflt df on df.kode = d.kode
  left join f f1 on f1.kat = k.kat and f1.kode = d.kode left join f f2 on f2.kat = k.kat and f2.kode = '*'),
baris as (
  select b.kat, replace(a.nama, '{U}', n.nama) aktivitas, a.tahap, b.tool, b.role, b.uom, b.kelas, round(b.dt * b.fk, 2) detik,
    case when b.uom in ('karton','palet') or (b.uom = 'pcs' and b.kelas = 'light') then 'Benchmark' else 'Asumsi' end metode, s.s sumber,
    'Dasar ' || round(b.dt::numeric, 1) || ' dtk/' || b.uom || case when b.fk <> 1 then ' x ' || b.fk || ': ' || fk.ket else '' end || '. Draft, validasi TMS.' catatan
  from dasar b join a on a.kode = b.kode join n on n.uom = b.uom join src2 s on s.kat = b.kat and s.uom = b.uom and s.kelas = b.kelas left join fk on fk.kat = b.kat
  union all
  select t.kat, replace(a.nama, '{U}', n.nama) || ' (setara ' || t.uom || ')', a.tahap, coalesce(d.tool, df.tool), coalesce(d.role, df.role), t.uom, 'semua',
    round(d.dt * coalesce(f1.v, f2.v, 1.0) / t.qty, 2), 'Asumsi', s.s,
    'Turunan ' || t.lbl || ': ' || round((d.dt * coalesce(f1.v, f2.v, 1.0))::numeric, 1) || ' dtk/' || t.au || ' ÷ ' || t.qty || ' ' || t.uom || '/' || t.au || '. Draft, validasi TMS.'
  from t join d on d.uom = t.au and d.kelas = t.ak and d.kode in ('unload','putaway','pick','load') join dflt df on df.kode = d.kode join a on a.kode = d.kode join n on n.uom = t.au
  join src2 s on s.kat = t.kat and s.uom = t.au and s.kelas = t.ak
  left join f f1 on f1.kat = t.kat and f1.kode = d.kode left join f f2 on f2.kat = t.kat and f2.kode = '*'
  union all
  select 'General Cargo', 'Cycle Count per Location', 'Inventory', 'RF', 'Stock Controller', 'lokasi', 'semua', 40, 'Asumsi', 'Benchmark internal Leca (GC); WERC DC Measures 2024 (73,8 line pick & ship/jam; 54,5 line receive & put away/jam)',
    'Hitung 1 lokasi rak (scan lokasi + SKU + qty) ±40 dtk; acuan internal cycle count 60 palet/jam. Draft.')
insert into public.productivity (aktivitas, tahap, tool, role_name, uom, kelas_berat, industri, prod_per_jam, metode, sumber, catatan, tanggal, status)
select distinct on (aktivitas, tool, uom, kelas, kat) aktivitas, tahap, tool, role, uom, kelas, kat, round(3600 / detik, 3), metode, sumber, catatan, date '2026-11-08', 'draft'::public.data_status
from baris
on conflict (aktivitas, tool, uom, kelas_berat, industri) do nothing;
